        "name": "FacetSearch.java",
        "code": "import java.util.*;\n\npublic class FacetSearch {\n    record Product(int id, String name, String brand, String color, int price) {}\n\n    static final List<Product> products = List.of(\n            new Product(1, \"Trail shoe\", \"Acme\", \"red\", 80),\n            new Product(2, \"Road shoe\", \"Acme\", \"blue\", 120),\n            new Product(3, \"Trail shoe\", \"Zeta\", \"red\", 95),\n            new Product(4, \"Sandal\", \"Zeta\", \"blue\", 40),\n            new Product(5, \"Boot\", \"Acme\", \"red\", 150));\n\n    // Inverted index per facet value: value -> set of product ids. Filters are set intersections.\n    static final Map<String, Set<Integer>> index = new HashMap<>();\n\n    static {\n        for (Product p : products) {\n            index.computeIfAbsent(\"brand=\" + p.brand(), k -> new TreeSet<>()).add(p.id());\n            index.computeIfAbsent(\"color=\" + p.color(), k -> new TreeSet<>()).add(p.id());\n        }\n    }\n\n    static Set<Integer> filter(String... facets) {\n        Set<Integer> result = null;\n        for (String f : facets) {\n            Set<Integer> ids = index.getOrDefault(f, Set.of());\n            if (result == null) result = new TreeSet<>(ids); else result.retainAll(ids);\n        }\n        return result == null ? new TreeSet<>(products.stream().map(Product::id).toList()) : result;\n    }\n\n    /** Facet counts for the current result: how many matches each other value would give (what the sidebar shows). */\n    static Map<String, Integer> counts(Set<Integer> current, String facetName) {\n        Map<String, Integer> out = new TreeMap<>();\n        for (var e : index.entrySet()) {\n            if (!e.getKey().startsWith(facetName + \"=\")) continue;\n            int n = 0;\n            for (int id : e.getValue()) if (current.contains(id)) n++;\n            out.put(e.getKey().substring(facetName.length() + 1), n);\n        }\n        return out;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(\"brand=Acme: \" + filter(\"brand=Acme\"));\n        System.out.println(\"brand=Acme and color=red: \" + filter(\"brand=Acme\", \"color=red\"));\n        Set<Integer> red = filter(\"color=red\");\n        System.out.println(\"with color=red selected, brand counts: \" + counts(red, \"brand\"));\n        System.out.println(\"with nothing selected, color counts: \" + counts(filter(), \"color\"));\n    }\n}"
